function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderMonthlySummary(rows) {
    const tbody = container.querySelector('#monthly-summary-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.集計年月 || ''}</td>
        <td>${(r.発注件数 || 0).toLocaleString()}</td>
        <td>¥${(r.発注総額 || 0).toLocaleString()}</td>
        <td>¥${(r.平均発注単価 || 0).toLocaleString()}</td>
        <td>${r.新規顧客数 || 0}</td>
        <td>${r.リピート顧客数 || 0}</td>
        <td><span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; background: ${r.集計ステータス === '完了' ? '#22c55e' : '#f59e0b'}; color: #fff;">${r.集計ステータス || ''}</span></td>
      </tr>
    `).join('');
  }

  function renderCustomerPriceComparison(rows) {
    const tbody = container.querySelector('#customer-price-tbody');
    tbody.innerHTML = rows.slice(0, 5).map(r => {
      const diff = (r.顧客単価 || 0) - (r.市場平均単価 || 0);
      const diffColor = diff > 0 ? '#ef4444' : '#22c55e';
      const diffSign = diff > 0 ? '+' : '';
      return `
        <tr data-id="${r.id}">
          <td style="font-size: 12px;">${r.顧客ID ? `顧客${r.顧客ID.slice(-4)}` : ''}</td>
          <td>¥${(r.顧客単価 || 0).toLocaleString()}</td>
          <td style="color: ${diffColor};">${diffSign}¥${diff.toLocaleString()}</td>
        </tr>
      `;
    }).join('');
  }

  // 2. チャート描画関数
  function drawRevenueChart() {
    const canvas = container.querySelector('#revenue-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.02)';
    ctx.fillRect(0, 0, width, height);

    // グリッド線
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    // データポイント
    const data = [8500000, 9200000, 10100000, 11800000, 12450000, 13200000];
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const maxValue = Math.max(...data);
    const minValue = Math.min(...data);
    const range = maxValue - minValue;

    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 3;
    ctx.beginPath();

    for (let i = 0; i < data.length; i++) {
      const x = 60 + (i * (width - 100) / (data.length - 1));
      const y = height - 40 - ((data[i] - minValue) / range) * (height - 80);

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // ポイント
      ctx.fillStyle = '#22c55e';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    for (let i = 0; i < months.length; i++) {
      const x = 60 + (i * (width - 100) / (months.length - 1));
      ctx.fillText(months[i], x, height - 10);
    }
  }

  function drawPatternChart() {
    const canvas = container.querySelector('#pattern-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.02)';
    ctx.fillRect(0, 0, width, height);

    // 棒グラフ
    const categories = ['電子部品', '資材', '工具', '機械', '消耗品'];
    const values = [35, 28, 22, 10, 5];
    const colors = ['#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6'];

    const barWidth = (width - 100) / categories.length;
    const maxValue = Math.max(...values);

    for (let i = 0; i < categories.length; i++) {
      const x = 50 + i * barWidth + barWidth * 0.1;
      const barHeight = (values[i] / maxValue) * (height - 80);
      const y = height - 40 - barHeight;

      ctx.fillStyle = colors[i];
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(categories[i], x + barWidth * 0.4, height - 10);

      // 値
      ctx.fillStyle = '#d0e4ff';
      ctx.fillText(values[i] + '%', x + barWidth * 0.4, y - 5);
    }
  }

  function drawMarketTrendChart() {
    const canvas = container.querySelector('#market-trend-chart');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.02)';
    ctx.fillRect(0, 0, width, height);

    // 複数の線グラフ
    const data1 = [100, 105, 98, 110, 115, 108];
    const data2 = [95, 102, 108, 105, 112, 118];

    // 線1（自社価格）
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < data1.length; i++) {
      const x = 30 + (i * (width - 60) / (data1.length - 1));
      const y = height - 30 - ((data1[i] - 90) / 30) * (height - 60);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 線2（市場平均）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < data2.length; i++) {
      const x = 30 + (i * (width - 60) / (data2.length - 1));
      const y = height - 30 - ((data2[i] - 90) / 30) * (height - 60);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#22c55e';
    ctx.fillRect(10, 10, 12, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText('自社価格', 25, 15);

    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(10, 20, 12, 3);
    ctx.fillText('市場平均', 25, 25);
  }

  // 3. 初期データ読み込み
  Promise.all([
    window.aivicApi.list(1), // 月次集計データ
    window.aivicApi.list(4)  // 顧客別単価比較分析結果
  ]).then(([monthlyData, customerData]) => {
    if (monthlyData) renderMonthlySummary(monthlyData);
    if (customerData) renderCustomerPriceComparison(customerData);

    // チャート描画
    drawRevenueChart();
    drawPatternChart();
    drawMarketTrendChart();
  });

  // 4. フィルターボタンのイベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', async () => {
    const selectedMonth = container.querySelector('#select-month').value;
    const checkedCategories = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);

    const monthlyData = await window.aivicApi.list(1);
    if (monthlyData) {
      let filtered = monthlyData;
      if (selectedMonth) {
        filtered = filtered.filter(r => r.集計年月 === selectedMonth);
      }
      renderMonthlySummary(filtered);
    }

    // チャート再描画
    drawRevenueChart();
    drawPatternChart();
    drawMarketTrendChart();
  });

  // 5. ナビゲーションボタンのイベントリスナー
  container.querySelector('#btn-order-detail').addEventListener('click', () => {
    window.showScreen("scr-1780291929523");
  });

  container.querySelector('#btn-pattern-detail').addEventListener('click', () => {
    window.showScreen("scr-1780291952461");
  });

  container.querySelector('#btn-strategy-detail').addEventListener('click', () => {
    window.showScreen("scr-1780291970530");
  });

  // 6. レポート生成ボタン
  container.querySelector('#btn-generate-report').addEventListener('click', async () => {
    const selectedMonth = container.querySelector('#select-month').value || new Date().toISOString().slice(0, 7);

    const reportData = {
      レポート名: `月次分析レポート_${selectedMonth}`,
      レポート種別: '月次集計分析',
      対象期間開始日: selectedMonth + '-01',
      対象期間終了日: selectedMonth + '-31',
      レポート内容: `${selectedMonth}の月次集計・分析結果\n売上: ¥12,450,000 (前月比+8.5%)\n発注件数: 1,247件\n価格競争力指数: 87.3`,
      ステータス: '完了',
      公開フラグ: true,
      通知済フラグ: false,
      作成者ID: 'system'
    };

    const saved = await window.aivicApi.save(5, reportData);
    if (saved) {
      alert('分析レポートを生成しました');
    }
  });

  // 7. データエクスポートボタン
  container.querySelector('#btn-export-data').addEventListener('click', async () => {
    const monthlyData = await window.aivicApi.list(1);
    if (!monthlyData) return;

    const headers = ['集計年月', '発注件数', '発注総額', '平均発注単価', '新規顧客数', 'リピート顧客数', '集計ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...monthlyData.map(row => [
        row.集計年月 || '',
        row.発注件数 || 0,
        row.発注総額 || 0,
        row.平均発注単価 || 0,
        row.新規顧客数 || 0,
        row.リピート顧客数 || 0,
        row.集計ステータス || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `月次集計データ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderPatternRows(rows) {
    const tbody = container.querySelector("#pattern-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.商品カテゴリ || ""}</td>
        <td>${r.平均発注間隔日数 || ""}日</td>
        <td>${r.推奨発注タイミング || ""}</td>
        <td>${r.信頼度スコア || ""}%</td>
      </tr>
    `).join("");
  }

  function renderRankingRows(rows) {
    const tbody = container.querySelector("#ranking-tbody");
    tbody.innerHTML = rows.slice(0, 10).map((r, index) => `
      <tr data-id="${r.id}">
        <td>${index + 1}</td>
        <td>${r.顧客セグメント || ""}</td>
        <td>¥${(r.発注総額 || 0).toLocaleString()}</td>
        <td style="color: ${(r.前月比発注総額 || 0) >= 0 ? '#22c55e' : '#ef4444'};">
          ${(r.前月比発注総額 || 0) >= 0 ? '+' : ''}${((r.前月比発注総額 || 0) / 10000).toFixed(1)}%
        </td>
      </tr>
    `).join("");
  }

  // チャート描画関数
  function drawFrequencyChart() {
    const canvas = container.querySelector("#frequency-chart");
    const ctx = canvas.getContext("2d");

    // 背景をクリア
    ctx.fillStyle = '#1a2a40';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 棒グラフを描画
    const data = [25, 45, 35, 20, 30, 40, 28];
    const labels = ['月', '火', '水', '木', '金', '土', '日'];
    const maxValue = Math.max(...data);

    ctx.fillStyle = '#22c55e';
    data.forEach((value, index) => {
      const barHeight = (value / maxValue) * 150;
      const x = 40 + index * 45;
      const y = 170 - barHeight;
      ctx.fillRect(x, y, 30, barHeight);
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    labels.forEach((label, index) => {
      ctx.fillText(label, 45 + index * 45, 190);
    });
  }

  function drawSeasonalChart() {
    const canvas = container.querySelector("#seasonal-chart");
    const ctx = canvas.getContext("2d");

    // 背景をクリア
    ctx.fillStyle = '#1a2a40';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 折れ線グラフを描画
    const data = [100, 120, 90, 110, 130, 95, 105, 125, 85, 115, 140, 100];
    const maxValue = Math.max(...data);
    const minValue = Math.min(...data);

    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((value, index) => {
      const x = 30 + (index * 30);
      const y = 30 + ((maxValue - value) / (maxValue - minValue)) * 140;
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#22c55e';
    data.forEach((value, index) => {
      const x = 30 + (index * 30);
      const y = 30 + ((maxValue - value) / (maxValue - minValue)) * 140;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });
  }

  // KPI更新関数
  function updateKPIs(patternData, monthlyData) {
    if (patternData && patternData.length > 0) {
      const avgInterval = patternData.reduce((sum, r) => sum + (r.平均発注間隔日数 || 0), 0) / patternData.length;
      container.querySelector("#kpi-interval").textContent = avgInterval.toFixed(1) + "日";

      const avgConfidence = patternData.reduce((sum, r) => sum + (r.信頼度スコア || 0), 0) / patternData.length;
      container.querySelector("#kpi-confidence").textContent = avgConfidence.toFixed(0) + "%";
    }

    if (monthlyData && monthlyData.length > 0) {
      const totalCustomers = monthlyData.reduce((sum, r) => sum + (r.リピート顧客数 || 0) + (r.新規顧客数 || 0), 0);
      const repeatCustomers = monthlyData.reduce((sum, r) => sum + (r.リピート顧客数 || 0), 0);
      const repeatRate = totalCustomers > 0 ? (repeatCustomers / totalCustomers) * 100 : 0;
      container.querySelector("#kpi-repeat").textContent = repeatRate.toFixed(1) + "%";
    }
  }

  // 2. 初期データ読み込み
  Promise.all([
    window.aivicApi.list(2), // 購買パターン分析結果
    window.aivicApi.list(1)  // 月次集計データ
  ]).then(([patternData, monthlyData]) => {
    if (patternData) renderPatternRows(patternData);
    if (monthlyData) renderRankingRows(monthlyData);
    updateKPIs(patternData, monthlyData);
    drawFrequencyChart();
    drawSeasonalChart();

    // 異常値アラート表示判定
    if (patternData && patternData.some(r => (r.信頼度スコア || 0) < 60)) {
      container.querySelector("#alert-panel").style.display = "block";
    }
  });

  // 3. 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const segment = container.querySelector("#select-segment").value;

    // フィルタリング条件でデータを再取得
    const [patternData, monthlyData] = await Promise.all([
      window.aivicApi.list(2),
      window.aivicApi.list(1)
    ]);

    let filteredPattern = patternData || [];
    let filteredMonthly = monthlyData || [];

    if (startDate && endDate) {
      filteredPattern = filteredPattern.filter(r => {
        const targetStart = new Date(r.分析対象期間開始日);
        return targetStart >= new Date(startDate) && targetStart <= new Date(endDate);
      });
    }

    if (segment) {
      filteredMonthly = filteredMonthly.filter(r => 
        (r.顧客セグメント || "").includes(segment)
      );
    }

    renderPatternRows(filteredPattern);
    renderRankingRows(filteredMonthly);
    updateKPIs(filteredPattern, filteredMonthly);
    drawFrequencyChart();
    drawSeasonalChart();
  });

  // 4. 画面遷移ボタン
  container.querySelector("#btn-order-data").addEventListener("click", () => {
    window.showScreen("scr-1780291929523");
  });

  container.querySelector("#btn-customer-price").addEventListener("click", () => {
    window.showScreen("scr-1780291980452");
  });

  // 5. 行クリックイベント（詳細表示）
  container.addEventListener("click", (e) => {
    const row = e.target.closest("tr[data-id]");
    if (row && row.dataset.id) {
      // 詳細情報をアラートで表示（簡易実装）
      const id = row.dataset.id;
      console.log("Selected pattern ID:", id);
    }
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderCustomerAnalysis(rows) {
    const tbody = container.querySelector("#customer-analysis-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID}">
        <td>${r.顧客名|| "未設定"}</td>
        <td>${r.商品カテゴリ || "未分類"}</td>
        <td style="text-align: right;">¥${(r.顧客単価 || 0).toLocaleString()}</td>
        <td style="text-align: right;">¥${(r.市場平均単価 || 0).toLocaleString()}</td>
        <td style="text-align: right; color: ${(r.単価差額 || 0) >= 0 ? '#22c55e' : '#ef4444'};">
          ${(r.単価差額 || 0) >= 0 ? '+' : ''}¥${(r.単価差額 || 0).toLocaleString()}
        </td>
        <td style="text-align: right; color: ${(r.単価差率 || 0) >= 0 ? '#22c55e' : '#ef4444'};">
          ${(r.単価差率 || 0) >= 0 ? '+' : ''}${r.単価差率 || 0}%
        </td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; 
                       background: ${r.価格競争力ランク === '高' ? 'rgba(34, 197, 94, 0.2)' : 
                                   r.価格競争力ランク === '中' ? 'rgba(251, 191, 36, 0.2)' : 'rgba(239, 68, 68, 0.2)'};
                       color: ${r.価格競争力ランク === '高' ? '#22c55e' : 
                               r.価格競争力ランク === '中' ? '#fbbf24' : '#ef4444'};">
            ${r.価格競争力ランク || "未評価"}
          </span>
        </td>
        <td style="text-align: right;">¥${(r.推奨価格 || 0).toLocaleString()}</td>
      </tr>
    `).join("");
  }

  function renderSensitivityAnalysis(rows) {
    const tbody = container.querySelector("#sensitivity-analysis-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID}">
        <td>${r.商品カテゴリ || "未分類"}</td>
        <td>${r.顧客セグメント || "未分類"}</td>
        <td>${r.価格弾力性 || "未算出"}</td>
        <td style="text-align: right;">¥${(r.推奨価格 || 0).toLocaleString()}</td>
        <td style="text-align: right; color: ${(r.売上予測増減率 || 0) >= 0 ? '#22c55e' : '#ef4444'};">
          ${(r.売上予測増減率 || 0) >= 0 ? '+' : ''}${r.売上予測増減率 || 0}%
        </td>
        <td style="text-align: right;">${r.利益率予測 || 0}%</td>
        <td>${r.信頼度 || "未評価"}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px;
                       background: ${r.承認状況 === '承認済' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(251, 191, 36, 0.2)'};
                       color: ${r.承認状況 === '承認済' ? '#22c55e' : '#fbbf24'};">
            ${r.承認状況 || "未承認"}
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(4).then(customerRows => {
    if (customerRows) renderCustomerAnalysis(customerRows);
  });

  window.aivicApi.list(3).then(strategyRows => {
    if (strategyRows) renderSensitivityAnalysis(strategyRows);
  });

  // 3. チャート描画
  function drawPriceTrendChart() {
    const canvas = container.querySelector("#price-trend-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    // 価格推移線
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    const points = [
      {x: 60, y: height * 0.7},
      {x: 120, y: height * 0.6},
      {x: 180, y: height * 0.65},
      {x: 240, y: height * 0.5},
      {x: 300, y: height * 0.45},
      {x: 360, y: height * 0.4}
    ];
    points.forEach((point, i) => {
      if (i === 0) ctx.moveTo(point.x, point.y);
      else ctx.lineTo(point.x, point.y);
    });
    ctx.stroke();

    // ラベル
    ctx.fillText('価格推移 (6ヶ月)', 10, 20);
  }

  function drawCompetitorChart() {
    const canvas = container.querySelector("#competitor-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';

    // 競合比較バー
    const bars = [
      {label: '当社', value: 0.8, color: '#3b82f6'},
