  // 再描画関数
  function renderComparisons(rows) {
    comparisonTbody.innerHTML = rows.map(r => {
      const diffRate = r.単価差率 || 0;
      const rank = r.価格競争力ランク || '-';
      const rankColor = rank === '高' ? '#22c55e' : rank === '中' ? '#f59e0b' : rank === '低' ? '#ef4444' : 'var(--text-muted)';

      return `
        <tr data-id="${r.分析結果ID}">
          <td class="text-xs">${r.顧客名|| '-'}</td>
          <td class="text-xs">${r.商品名 || '-'}</td>
          <td class="text-xs">¥${(r.顧客単価 || 0).toLocaleString()}</td>
          <td class="text-xs">¥${(r.市場平均単価 || 0).toLocaleString()}</td>
          <td class="text-xs" style="color: ${diffRate > 0 ? '#22c55e' : diffRate < 0 ? '#ef4444' : 'var(--text)'}">
            ${diffRate > 0 ? '+' : ''}${diffRate}%
          </td>
          <td class="text-xs" style="color: ${rankColor}">${rank}</td>
          <td class="text-xs">
            <button class="action-btn secondary text-xs px-2 py-1 detail-btn" data-id="${r.分析結果ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // KPI更新
  function updateKPIs(rows) {
    const customerCount = new Set(rows.map(r => r.顧客ID)).size;
    const avgDiff = rows.length > 0 ? (rows.reduce((sum, r) => sum + (r.単価差率 || 0), 0) / rows.length).toFixed(1) : 0;
    const recommendations = rows.filter(r => r.価格改定推奨フラグ).length;
    const totalImpact = rows.reduce((sum, r) => sum + ((r.推奨価格 || 0) - (r.顧客単価 || 0)) * (r.取引数量 || 0), 0);

    container.querySelector('#kpi-customers').textContent = `${customerCount}社`;
    container.querySelector('#kpi-avg-diff').textContent = `${avgDiff}%`;
    container.querySelector('#kpi-recommendations').textContent = `${recommendations}件`;
    container.querySelector('#kpi-impact').textContent = `¥${totalImpact.toLocaleString()}`;
  }

  // 戦略提案更新
  function updateStrategy(rows) {
    const priceUp = rows.filter(r => (r.単価差率 || 0) < -5).length;
    const priceDown = rows.filter(r => (r.単価差率 || 0) > 10).length;
    const priceOk = rows.filter(r => Math.abs(r.単価差率 || 0) <= 5).length;

    container.querySelector('#price-up-count').textContent = `${priceUp}件の商品で値上げ余地あり`;
    container.querySelector('#price-down-count').textContent = `${priceDown}件の商品で競争力不足`;
    container.querySelector('#price-ok-count').textContent = `${priceOk}件の商品が適正範囲`;

    const actionList = container.querySelector('#action-list');
    const actions = [];
    if (priceUp > 0) actions.push(`${priceUp}件の商品で段階的な値上げを検討`);
    if (priceDown > 0) actions.push(`${priceDown}件の商品で価格競争力の改善が必要`);
    if (actions.length === 0) actions.push('現在の価格戦略は適正です');

    actionList.innerHTML = actions.map(action => `<div>• ${action}</div>`).join('');
  }

  // トレンドグラフ描画
  function drawTrendChart(data = []) {
    ctx.clearRect(0, 0, trendChart.width, trendChart.height);

    if (data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('顧客と商品を選択してください', trendChart.width / 2, trendChart.height / 2);
      return;
    }

    const margin = 40;
    const chartWidth = trendChart.width - margin * 2;
    const chartHeight = trendChart.height - margin * 2;

    // サンプルデータでグラフ描画
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const customerPrices = [1200, 1180, 1220, 1250, 1230, 1240];
    const marketPrices = [1150, 1160, 1170, 1180, 1190, 1200];

    const maxPrice = Math.max(...customerPrices, ...marketPrices) * 1.1;
    const minPrice = Math.min(...customerPrices, ...marketPrices) * 0.9;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin, margin);
    ctx.lineTo(margin, margin + chartHeight);
    ctx.lineTo(margin + chartWidth, margin + chartHeight);
    ctx.stroke();

    // 顧客単価線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    customerPrices.forEach((price, i) => {
      const x = margin + (i / (customerPrices.length - 1)) * chartWidth;
      const y = margin + chartHeight - ((price - minPrice) / (maxPrice - minPrice)) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 市場単価線
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    marketPrices.forEach((price, i) => {
      const x = margin + (i / (marketPrices.length - 1)) * chartWidth;
      const y = margin + chartHeight - ((price - minPrice) / (maxPrice - minPrice)) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(margin + chartWidth - 120, margin + 10, 12, 2);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText('顧客単価', margin + chartWidth - 100, margin + 15);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(margin + chartWidth - 120, margin + 25, 12, 2);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('市場単価', margin + chartWidth - 100, margin + 30);
  }

  // フィルタリング
  function applyFilters() {
    const customer = container.querySelector('#customer-filter').value;
    const category = container.querySelector('#category-filter').value;
    const rank = container.querySelector('#rank-filter').value;
