      if (!rows) return;

      let filtered = rows.filter(r => {
        if (customer && !r.顧客名?.includes(customer)) return false;
        if (category && !r.商品カテゴリ?.includes(category)) return false;
        if (rank && r.価格競争力ランク !== rank) return false;
        if (startDate && r.分析対象期間開始日 && new Date(r.分析対象期間開始日) < new Date(startDate)) return false;
        if (endDate && r.分析対象期間終了日 && new Date(r.分析対象期間終了日) > new Date(endDate)) return false;
        return true;
      });

      renderComparisons(filtered);
      updateKPIs(filtered);
      updateStrategy(filtered);
    });
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(4).then(rows => {
      if (!rows) return;

      const headers = ['顧客名', '商品名', '顧客単価', '市場平均単価', '単価差額', '単価差率', '価格競争力ランク', '推奨価格'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(r => [
          r.顧客名 || '',
          r.商品名 || '',
          r.顧客単価 || 0,
          r.市場平均単価 || 0,
          r.単価差額 || 0,
          r.単価差率 || 0,
          r.価格競争力ランク || '',
          r.推奨価格 || 0
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '顧客別単価比較分析.csv';
      link.click();
    });
  }

  // 初期データ表示
  const initialData = tables[4]?.records || [];
  renderComparisons(initialData);
  updateKPIs(initialData);
  updateStrategy(initialData);
  drawTrendChart();

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#customer-filter').value = '';
    container.querySelector('#category-filter').value = '';
