      status: container.querySelector('#modal-status').value,
      staff_name: container.querySelector('#modal-staff').value,
      negotiation_date: container.querySelector('#modal-negotiation-date').value,
      follow_date: container.querySelector('#modal-follow-date').value,
      notes: container.querySelector('#modal-notes').value
    };

    if (!data.customer_name || !data.product_name) {
      alert('顧客名と商品名は必須です');
      return;
    }

    let result;
    if (currentEditId) {
      result = await window.aivicApi.update(0, currentEditId, data);
    } else {
      result = await window.aivicApi.save(0, data);
    }

    if (result) {
      closeModal();
      window.aivicApi.list(0).then(renderRows);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      window.aivicApi.list(0).then(rows => {
        const record = rows?.find(r => r.id === id);
        if (record) openModal(record);
      });
    }

    if (deleteBtn) {
      if (!confirm('この交渉履歴を削除しますか？')) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      window.aivicApi.list(0).then(renderRows);
    }
  });

  // 画面遷移ボタン
  container.querySelector('#btn-analysis').addEventListener('click', () => {
    window.showScreen("scr-1780291980452");
  });

  container.querySelector('#btn-order-data').addEventListener('click', () => {
    window.showScreen("scr-1780291929523");
  });
}
